pool = json.load(open('pool.json'))
byid = {p['id']: p for p in pool}
assert len(R) == len(pool) == 109, (len(R), len(pool))
dossiers = {}
for r in R:
    i, med, top, p, mo, cap, dur, op, fit, key, sk = r
    dossiers[i] = dict(id=i, income_median_y2_usd=med, income_top_decile_usd=top, prob_reach_median=p, months_to_first_dollar=mo,
                       capital_required_usd=cap, durability_5yr=dur, openness=op, fit_profile=fit, key_numbers=key, skeptic=sk,
                       ev=round(med*p), fatal=('Fatal' in sk or 'Near-fatal' in sk))
json.dump(dossiers, open('dossiers.json','w'), indent=1)
def money(n): return '$'+format(int(n),',')
cards=[]
for p in pool:
    d=dossiers[p['id']]
    cards.append(f"[{p['id']}] {p['name']} | type={p['type']} form={p['form']} cat={p['category']}\n  thesis: {p['thesis'][:260]}\n  numbers: median-y2 {money(d['income_median_y2_usd'])} | top-decile {money(d['income_top_decile_usd'])} | p(median)={d['prob_reach_median']} | EV {money(d['ev'])} | first$ {d['months_to_first_dollar']}mo | capital {money(d['capital_required_usd'])} | durability {d['durability_5yr']}/10 | openness {d['openness']}/10 | fit {d['fit_profile']}/10\n  evidence: {d['key_numbers']}\n  skeptic: {d['skeptic']}")
open('cards.txt','w').write('\n\n'.join(cards))
rank = sorted(dossiers.values(), key=lambda d: -d['ev'])
print('cards chars', len('\n\n'.join(cards)))
print('EV top 25:')
for d in rank[:25]: print(f"  {d['id']} EV {money(d['ev'])} med {money(d['income_median_y2_usd'])} p {d['prob_reach_median']} top {money(d['income_top_decile_usd'])} | {byid[d['id']]['name'][:70]}")
print('flagged fatal/near-fatal:', [d['id'] for d in dossiers.values() if d['fatal']])
